class Cycle:
    def __init__(self, seq):
        self.seq = seq
        self.idx = 0
    def __iter__(self):
        return self
    def __next__(self):
        if not self.seq:
            raise StopIteration
        val = self.seq[self.idx]
        self.idx = (self.idx + 1) % len(self.seq)
        return val

