T = TypeVar('T', bound=Callable[..., int])

def int_cache(func: T) -> T:
    cache = {}
    @wraps(func)
    def wrapper(*args):
        if args in cache:
            return cache[args]
        result = func(*args)
        if not isinstance(result, int):
            raise TypeError('Return value must be int')
        cache[args] = result
        return result
    return wrapper  # type: ignore

